def table(rows,widths=None,compact=False):
    data=[[p(str(c),small) if not isinstance(c,(Image,Paragraph,list)) else c for c in row] for row in rows]
    t=Table(data,colWidths=widths or [W/len(rows[0])]*len(rows[0]),repeatRows=1,hAlign='LEFT')
    t.setStyle(TableStyle([('GRID',(0,0),(-1,-1),.5,colors.HexColor('#777777')),('BACKGROUND',(0,0),(-1,0),colors.HexColor('#EAEAEA')),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),6),('RIGHTPADDING',(0,0),(-1,-1),6),('TOPPADDING',(0,0),(-1,-1),5),('BOTTOMPADDING',(0,0),(-1,-1),5)]))
    if compact:t.setStyle(TableStyle([('TOPPADDING',(0,0),(-1,-1),2),('BOTTOMPADDING',(0,0),(-1,-1),2)]))
    story.append(t);story.append(Spacer(1,9))
def img(name,width=W,maxh=155*mm):
    path=ROOT/'docs/screenshots'/name
    im=PILImage.open(path); w,h=im.size; scale=min(width/w,maxh/h)
    return Image(str(path),width=w*scale,height=h*scale)
def figure(name,label,maxh=145*mm):
    story.extend([img(name,maxh=maxh),p(label,caption)])
def footer(c,d):
    if d.page>1:
        c.setFont('Times',12);c.drawCentredString(105*mm,12*mm,str(d.page))

